createPet().then(petId => {
  cy.request({
    method: 'PUT',
    url: `${baseUrl}/pet`,
    body: {
      id: petId,
      category: petData.category,
      name: petData.updatedName,
      photoUrls: petData.photoUrls,
      tags: petData.tags,
      status: 'sold'
    }
  }).then(updateResponse => {
    expect(updateResponse.status).to.eq(200);
    cy.request({
      method: 'GET',
      url: `${baseUrl}/pet/findByStatus`,
      qs: {
        status: 'sold'
      }
    }).then(response => {
      expect(response.status).to.eq(200);
      expect(response.body).to.be.an('array');
      const updatedPet = response.body.find(pet => pet.id === petId);
      expect(updatedPet).to.not.be.undefined;
      expect(updatedPet.name).to.eq(petData.updatedName);
      expect(updatedPet.status).to.eq('sold');
    });
  });
});

